import Toybox.Lang;
import Toybox.Math;

// Solar position from Astronomical Almanac approximations; lunar position
// from Lunar (Meeus periodic ephemeris). Double day counts avoid 32-bit
// Float loss of sidereal precision. All returned angles are degrees.
module Astro {

    const RAD = 0.017453292519943295d;

    function w360(x as Numeric) as Double {
        var v = x.toDouble();
        var n = (v / 360.0d).toLong();
        var r = v - n * 360.0d;
        if (r < 0.0d) {
            r += 360.0d;
        }
        return r;
    }

    function w180(x as Numeric) as Double {
        var r = w360(x);
        return (r > 180.0d) ? r - 360.0d : r;
    }

    function sind(x as Numeric) as Double {
        return Math.sin(x.toDouble() * RAD).toDouble();
    }

    function cosd(x as Numeric) as Double {
        return Math.cos(x.toDouble() * RAD).toDouble();
    }

    function asind(x as Numeric) as Double {
        var v = x.toDouble();
        if (v > 1.0d) { v = 1.0d; }
        if (v < -1.0d) { v = -1.0d; }
        return (Math.asin(v) / RAD).toDouble();
    }

    function atan2d(y as Numeric, x as Numeric) as Double {
        return (Math.atan2(y.toDouble(), x.toDouble()) / RAD).toDouble();
    }

    // Project the local sky onto the east/up/west plane of the dial. This
    // places the Moon above/below the horizontal diameter with its apparent
    // altitude, rather than assuming that +/-90 degrees of hour angle is
    // the local horizon. The north/south component is intentionally omitted.
    function moonRingAngle(hourAngle as Numeric, altitude as Numeric, azimuth as Numeric) as Float {
        var west = -cosd(altitude) * sind(azimuth);
        var up = sind(altitude);
        // At the north/south horizon the projection has no direction.
        // Use the rising/setting side without dividing by a near-zero norm.
        if (west * west + up * up < 0.00000000000000000001d) {
            return (hourAngle < 0) ? -90.0 : 90.0;
        }
        return atan2d(west, up).toFloat();
    }

    // Hour angle (degrees, 0..180) at which the sun sits at altitude h0.
    // 180 = never goes below h0 that day, 0 = never reaches h0.
    function hourAngle(h0 as Numeric, lat as Numeric, dec as Numeric) as Double {
        var c = (sind(h0) - sind(lat) * sind(dec)) / (cosd(lat) * cosd(dec));
        if (c <= -1.0d) { return 180.0d; }
        if (c >= 1.0d) { return 0.0d; }
        return (Math.acos(c) / RAD).toDouble();
    }

    // unix: UTC seconds. lat/lon: degrees (east positive). tzSec: local offset incl. DST.
    function compute(unix as Number, lat as Float, lon as Float, tzSec as Number) as Dictionary {
        var d = unix.toDouble() / 86400.0d - 10957.5d;   // days since J2000.0

        // --- Sun ---
        var g = w360(357.529d + 0.98560028d * d);
        var q = w360(280.459d + 0.98564736d * d);
        var sunLon = w360(q + 1.915d * sind(g) + 0.020d * sind(2.0d * g));
        var eps = 23.439d - 0.00000036d * d;
        var sunRa = w360(atan2d(cosd(eps) * sind(sunLon), cosd(sunLon)));
        var sunDec = asind(sind(eps) * sind(sunLon));
        var eqtMin = w180(q - sunRa) * 4.0d;              // equation of time, minutes

        var utcH = (unix % 86400).toDouble() / 3600.0d;
        var meanH = w360((utcH + lon / 15.0d) * 15.0d) / 15.0d;                  // mean solar time
        var trueH = w360((utcH + lon / 15.0d + eqtMin / 60.0d) * 15.0d) / 15.0d; // sundial time
        var sunH = (trueH - 12.0d) * 15.0d;               // hour angle, -180..180, 0 = solar noon

        // Sun elevation above the horizon now, and today's maximum (at solar noon).
        var sunAlt = asind(sind(lat) * sind(sunDec) + cosd(lat) * cosd(sunDec) * cosd(sunH));
        var peak = 90.0d - (lat.toDouble() - sunDec).abs();

        var hRise = hourAngle(-0.833d, lat, sunDec);
        var hGold = hourAngle(6.0d, lat, sunDec);
        var hCivil = hourAngle(-6.0d, lat, sunDec);
        var hNaut = hourAngle(-12.0d, lat, sunDec);
        var hAstro = hourAngle(-18.0d, lat, sunDec);

        // Local clock minutes of sunrise / sunset (-1 when the sun does not rise or set).
        var noonUtcH = 12.0d - lon / 15.0d - eqtMin / 60.0d;
        var tzH = tzSec.toDouble() / 3600.0d;
        var riseMin = -1;
        var setMin = -1;
        if (hRise > 0.0d && hRise < 180.0d) {
            riseMin = (w360((noonUtcH - hRise / 15.0d + tzH) * 15.0d) / 15.0d * 60.0d + 0.5d).toNumber() % 1440;
            setMin = (w360((noonUtcH + hRise / 15.0d + tzH) * 15.0d) / 15.0d * 60.0d + 0.5d).toNumber() % 1440;
        }

        // Minutes until the next horizon crossing.
        var up = (sunH > -hRise) && (sunH < hRise);
        var toNext;
        if (up) {
            toNext = hRise - sunH;
        } else if (sunH >= hRise) {
            toNext = 360.0d - sunH - hRise;
        } else {
            toNext = -hRise - sunH;
        }

        // Lunar periodic ephemeris: phase, local hour angle, apparent altitude.
        var lunar = Lunar.position(unix, lat, lon);

        return {
            :sunH => sunH.toFloat(),
            :alt => sunAlt.toFloat(),
            :peak => peak.toFloat(),
            :trueMin => (trueH * 60.0d).toNumber() % 1440,
            :meanMin => (meanH * 60.0d).toNumber() % 1440,
            :hRise => hRise.toFloat(),
            :hGold => hGold.toFloat(),
            :hCivil => hCivil.toFloat(),
            :hNaut => hNaut.toFloat(),
            :hAstro => hAstro.toFloat(),
            :riseMin => riseMin,
            :setMin => setMin,
            :sunUp => up,
            :nextMin => (toNext / 15.0d * 60.0d).toNumber(),
            :moonH => lunar[:hourAngle],
            :moonRing => moonRingAngle(lunar[:hourAngle], lunar[:altitude], lunar[:azimuth]),
            :moonAlt => lunar[:altitude],
            :moonUp => lunar[:horizon] > 0,
            :moonAz => lunar[:azimuth],
            :illum => lunar[:illumination],
            :waxing => lunar[:waxing],
            :south => lat < 0.0
        };
    }
}

import Toybox.Lang;

// Colors for charts, UV risk, and weather artwork. HR/stress bands are display
// choices; UV uses the standard EPA/NWS exposure categories.
module ChartColors {
    const PURPLE = 0xA64DFF;
    const BLUE = 0x2D7DFF;
    const GREEN = 0x19E68C;
    const YELLOW = 0xFFE338;
    const ORANGE = 0xFF8A22;
    const RED = 0xFF4048;
    const WEATHER_SUN = 0xFFF000;   // saturated lemon; matches Pal.SUN
    const WEATHER_MOON = 0xBD80FF;  // vivid lavender
    const WEATHER_CLOUD = 0xDCEBFF; // bright cool silver, also used by cloud overlays
    const WEATHER_FOG = 0x33E1C6;   // vivid teal
    const WEATHER_RAIN = 0x258CFF;  // saturated blue
    const WEATHER_SNOW = 0x26E6FF;  // icy cyan
    const WEATHER_WIND = 0x34F0A0;  // bright mint
    const WEATHER_HUMIDITY = 0x329BFF; // vivid blue RH droplet; distinct from dew point

    // Glyph selection still comes from Garmin conditions and the existing
    // solar day/night check. These colors affect weather artwork only.
    // String == tests identity in Monkey C; compare contents across modules.
    function condition(glyph as String) as Number {
        if (glyph.equals("c") || glyph.equals("p") || glyph.equals("t")) { return WEATHER_SUN; }
        if (glyph.equals("n") || glyph.equals("q")) { return WEATHER_MOON; }
        if (glyph.equals("C")) { return WEATHER_CLOUD; }
        if (glyph.equals("f")) { return WEATHER_FOG; }
        if (glyph.equals("r")) { return WEATHER_RAIN; }
        if (glyph.equals("s")) { return WEATHER_SNOW; }
        if (glyph.equals("w")) { return WEATHER_WIND; }
        return Pal.DIMMER;
    }

    // The caller passes the same rounded whole index shown on screen. Missing
    // data is neutral, not a low-risk green zero. UV has no upper category cap.
    function uvIndex(shown) as Number {
        if (!(shown instanceof Number) || shown < 0) { return Pal.DIMMER; }
        if (shown <= 2) { return GREEN; }
        if (shown <= 5) { return YELLOW; }
        if (shown <= 7) { return ORANGE; }
        if (shown <= 10) { return RED; }
        return PURPLE;
    }

    // Use the measured BPM (including averaged samples), never the sparkline's
    // auto-scaled height, so the same rate has the same color on every day.
    function heartRate(bpm) as Number {
        if (bpm == null || bpm <= 0) { return Pal.TRACK; }
        if (bpm < 60) { return PURPLE; }
        if (bpm < 70) { return BLUE; }
        if (bpm < 90) { return GREEN; }
        if (bpm < 110) { return YELLOW; }
        if (bpm < 130) { return ORANGE; }
        return RED;
    }

    // Garmin rest is 0-25. Purple is only a visual subdivision of that range;
    // a low stress reading does not identify sleep or a sleep stage.
    // All filled meter segments use this one current-reading color.
    function stress(level) as Number {
        if (level == null || level < 0 || level > 100) { return Pal.TRACK; }
        var shown = Fmt.round(level); // Match the whole-number stress readout.
        if (shown < 15) { return PURPLE; }
        if (shown <= 25) { return BLUE; }
        if (shown <= 50) { return GREEN; }
        if (shown <= 65) { return YELLOW; }
        if (shown <= 75) { return ORANGE; }
        return RED;
    }

    // A missing/invalid goal does not mean achieved. Only the goal reported for
    // this exact date can turn its bar yellow; missing step days remain grey.
    function steps(count, goal) as Number {
        if (count == null || count < 0) { return Pal.TRACK; }
        if (goal instanceof Number && goal > 0 && count >= goal) { return YELLOW; }
        return GREEN;
    }
}

import Toybox.Lang;
import Toybox.Math;

// Rolling steps use local calendar dates, not seven records or elapsed 24-hour
// intervals. The latter both fail when history is sparse or a DST day is 23 h.
module DaySteps {
    var beforeMonth as Array<Number> = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];

    function dayNumber(year as Number, month as Number, day as Number) as Number {
        var y = year - 1;
        var total = 365 * y + Math.floor(y / 4.0d).toNumber()
            - Math.floor(y / 100.0d).toNumber() + Math.floor(y / 400.0d).toNumber()
            + beforeMonth[month - 1] + day;
        if (month > 2 && year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            total += 1;
        }
        return total;
    }

    // Each input record is [serial local date, steps, optional step goal].
    // The original three-argument entry point keeps callers without goals valid.
    function summarize(today as Number, liveSteps, records as Array) as Dictionary {
        return summarizeWithGoals(today, liveSteps, null, records);
    }

    // Null means unavailable;
    // an explicit zero is a valid measured day. Ignore duplicates, future days,
    // older days, and today's history because the live counter owns today.
    // Goals belong to the same accepted daily record as the steps. In particular,
    // today's adaptive goal must never be substituted for an unknown past goal.
    function summarizeWithGoals(today as Number, liveSteps, liveGoal, records as Array) as Dictionary {
        var bars = new [7] as Array<Number or Null>;
        var goals = new [7] as Array<Number or Null>;
        for (var i = 0; i < 7; i++) { bars[i] = null; goals[i] = null; }
        if (liveSteps instanceof Number && liveSteps >= 0) {
            bars[6] = liveSteps;
            if (liveGoal instanceof Number && liveGoal > 0) { goals[6] = liveGoal; }
        }
        for (var j = 0; j < records.size(); j++) {
            var r = records[j];
            if (!(r instanceof Array) || r.size() < 2 || r.size() > 3
                    || !(r[0] instanceof Number) || !(r[1] instanceof Number) || r[1] < 0) {
                continue;
            }
            var index = r[0] - today + 6;
            if (index >= 0 && index < 6 && bars[index] == null) {
                bars[index] = r[1];
                if (r.size() == 3 && r[2] instanceof Number && r[2] > 0) {
                    goals[index] = r[2];
                }
            }
        }
        var total = 0;
        var found = 0;
        for (var k = 0; k < 7; k++) {
            if (bars[k] != null) {
                total += bars[k];
                found += 1;
            }
        }
        return {:sum => found > 0 ? total : null, :count => found,
                :complete => found == 7, :bars => bars, :goals => goals};
    }
}

import Toybox.Lang;

// Bright text and fixed icon accents on true black (AMOLED).
module Pal {
    const INK = 0xF1EBDF;
    const DIM = 0xE2DDD4;      // small labels: warm off-white, never dark grey
    const DIMMER = 0xDCD8D0;   // units and secondary labels remain readable
    const CORAL = 0xFF7B6B;   // body
    const MINT = 0x5FD6A4;    // movement
    const SKY = 0x7CB6FF;     // environment
    const DEW = 0xB275FF;     // vivid violet dew-point thermometer/drop; distinct from RH blue
    const GOLD = 0xFFC46B;    // sun / solar time
    const SUN = 0xFFF000;     // saturated lemon for sun artwork, without a white blend
    const HALO = 0x33271A;    // GOLD at ~20% over black
    const RISE_ICON = 0xFF995C; // orange arrow / horizon beneath a yellow sun
    const SET_ICON = 0x7CB6FF;  // blue arrow / horizon beneath a yellow sun
    const TRACK = 0x2C2C31;
    const TICK = 0x6D685E;
    const PEAK_ICON = 0xFFF000;   // noon-peak sun matches the other sun artwork
    const PEAK_TEXT = 0xFFE0A0;
    const ALT_ICON = 0xD9A95C;    // current sun elevation in the solar line
    const ALT_TEXT = 0xFFE0A0;
    const MOON_LIT = 0xE4E6F6;
    const MOON_DARK = 0x262940;


    function scale(c as Number, f as Float) as Number {
        var r = (((c >> 16) & 0xFF) * f).toNumber();
        var g = (((c >> 8) & 0xFF) * f).toNumber();
        var b = ((c & 0xFF) * f).toNumber();
        return (r << 16) | (g << 8) | b;
    }

    function lerp(c1 as Number, c2 as Number, f as Float) as Number {
        var r1 = (c1 >> 16) & 0xFF;
        var g1 = (c1 >> 8) & 0xFF;
        var b1 = c1 & 0xFF;
        var r = (r1 + (((c2 >> 16) & 0xFF) - r1) * f + 0.5).toNumber();
        var g = (g1 + (((c2 >> 8) & 0xFF) - g1) * f + 0.5).toNumber();
        var b = (b1 + ((c2 & 0xFF) - b1) * f + 0.5).toNumber();
        return (r << 16) | (g << 8) | b;
    }
}

module Fmt {

    // 60690 -> "60,690"
    function thousands(n as Number) as String {
        var neg = n < 0;
        var chars = (neg ? -n : n).format("%d").toCharArray();
        var len = chars.size();
        var out = "";
        for (var i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                out += ",";
            }
            out += chars[i];
        }
        return neg ? "-" + out : out;
    }

    // Minutes after midnight -> "7:07" (12 h, no suffix) or "19:07" (24 h).
    function clock(mins as Number, is24 as Boolean) as String {
        var m = ((mins % 1440) + 1440) % 1440;
        var h = m / 60;
        var mm = m % 60;
        if (!is24) {
            h = h % 12;
            if (h == 0) {
                h = 12;
            }
            return h.format("%d") + ":" + mm.format("%02d");
        }
        return h.format("%02d") + ":" + mm.format("%02d");
    }

    // 190 -> "3h 10m", 45 -> "45m"
    function duration(mins as Number) as String {
        if (mins < 60) {
            return mins.format("%d") + "m";
        }
        return (mins / 60).format("%d") + "h " + (mins % 60).format("%d") + "m";
    }

    // Weather observation age: "30m", "2h"
    function age(mins as Number) as String {
        if (mins < 90) {
            return mins.format("%d") + "m";
        }
        return ((mins + 30) / 60).format("%d") + "h";
    }

    function round(x as Numeric) as Number {
        var f = x.toFloat();
        return (f < 0.0) ? (f - 0.5).toNumber() : (f + 0.5).toNumber();
    }
}

import Toybox.Lang;

// Small, fixed-memory accumulator shared by the HR and stress sparklines.
// The caller supplies measured native history samples, never a held live value.
// A fresh instance anchors every rebuild to that refresh's UTC clock, including
// after a clock correction; missing/invalid samples remain gaps.
class HistoryBuckets {
    const COUNT = 24;
    const SPAN_SEC = 14400;
    const BUCKET_SEC = 600;

    private var mEnd as Number;
    private var mStart as Number;
    private var mMin as Numeric;
    private var mMax as Numeric;
    private var mSums as Array;
    private var mCounts as Array;

    function initialize(now as Number, minValue as Numeric, maxValue as Numeric) {
        mEnd = now;
        mStart = now - SPAN_SEC;
        mMin = minValue;
        mMax = maxValue;
        mSums = new [COUNT];
        mCounts = new [COUNT];
        for (var i = 0; i < COUNT; i++) {
            mSums[i] = 0;
            mCounts[i] = 0;
        }
    }

    // Inclusive window endpoints. An exact-now sample belongs to the final
    // bucket; each interior ten-minute boundary starts the following bucket.
    // SensorSample.data is Number/Float/null. Positive range comparisons also
    // reject non-finite values rather than letting them poison an average.
    function add(when, value) as Void {
        if (!(when instanceof Number) || when < mStart || when > mEnd
                || !(value instanceof Number || value instanceof Float)
                || !(value >= mMin && value <= mMax)) {
            return;
        }
        var index = (when - mStart) / BUCKET_SEC;
        if (index == COUNT) { index = COUNT - 1; }
        mSums[index] += value;
        mCounts[index] += 1;
    }

    // Oldest to newest. A measured stress zero is 0.0, not null.
    // Finish is repeatable and does not mutate the accumulated samples.
    function finish() as Array {
        var out = new [COUNT];
        for (var i = 0; i < COUNT; i++) {
            out[i] = mCounts[i] > 0 ? mSums[i].toFloat() / mCounts[i] : null;
        }
        return out;
    }
}

import Toybox.Lang;

// Display Garmin ActivityMonitor's raw whole hours. No complication minutes,
// private countdown, wake-time suppression, or source arbitration.
module RecoveryTime {
    function validHours(value) {
        return (value instanceof Number && value >= 0) ? value : null;
    }

    function displayHours(hours) as Dictionary {
        hours = validHours(hours);
        if (hours == null) {
            return { :value => "--", :unit => null, :label => "RECOVERY" };
        }
        // READY is the requested caption for Garmin reporting zero whole hours.
        // Keep 0h visible: the underlying source remains hour-resolution data.
        return { :value => hours.format("%d"), :unit => "h", :label => (hours == 0) ? "READY" : "RECOVERY" };
    }
}

